#!/usr/bin/env bash
set -euo pipefail
mkdir -p android/app/src/main/kotlin/com/personaltrainer/ia android/app/src/main/res/values android/app/src/main/res/drawable
cp tools/android/MainActivity.kt android/app/src/main/kotlin/com/personaltrainer/ia/MainActivity.kt
cp tools/android/RestAlarmReceiver.kt android/app/src/main/kotlin/com/personaltrainer/ia/RestAlarmReceiver.kt
cp tools/android/AndroidManifest.xml android/app/src/main/AndroidManifest.xml
cp tools/android/app_icon.xml android/app/src/main/res/drawable/app_icon.xml
# applicationId/namespace generated by flutter create are normalized
sed -i 's/namespace = .*/namespace = "com.personaltrainer.ia"/' android/app/build.gradle.kts || true
sed -i 's/applicationId = .*/applicationId = "com.personaltrainer.ia"/' android/app/build.gradle.kts || true
